def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    if not cwd.startswith('/') or cwd != cwd.rstrip('/') or cwd == '':
        return None

    link_count = 0

    # Normalize the input path
    if path.startswith('/'):
        current = ''
    else:
        current = cwd

    # Split path into components
    components = path.split('/')

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent directory
            if current:
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = ''
                else:
                    current = current[:last_slash]
            i += 1
            continue

        # Append the component
        if current == '':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]

            # Resolve remaining components after this one
            remaining = components[i+1:]

            # Process the target
            if target.startswith('/'):
                current = ''
                target_components = target.split('/')
            else:
                # Target is relative to the directory containing the link
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = ''
                else:
                    current = current[:last_slash]
                target_components = target.split('/')

            # Prepend target components to remaining components
            components = target_components + remaining
            i = 0
            continue

        i += 1

    # Return the result
    if current == '':
        return '/'
    return current

